import { str, num, missingAnswers, type Answers, type Option, type Section } from './assessmentCore';

export type HomeToolKey =
  | 'fire_risk_assessment' | 'fire_safety_checks' | 'evacuation' | 'window_restrictors' | 'hot_water'
  | 'legionella' | 'coshh' | 'lifting_equipment' | 'night_working' | 'oxygen_storage' | 'electrical_gas';

export type Severity = 'critical' | 'major' | 'minor';
export interface CheckOption extends Option { fail?: Severity; action?: string }
export interface Failure { severity: Severity; question: string; action: string }

/** What the home's own records say, for checks that depend on residents. */
export interface HomeContext {
  residents?: number;
  /** Residents with no current PEEP. */
  noPeep?: number;
  peepRed?: number;
  peepAmber?: number;
  /** The most staff any one resident needs to evacuate at night. */
  maxNightStaffForOne?: number;
  /** Residents whose PEEP needs evacuation equipment. */
  needEquipment?: number;
  oxygenUsers?: number;
  emollientFireRisk?: number;
  smokers?: number;
}

export interface HomeResult {
  complete: boolean;
  missing: string[];
  errors: string[];
  level: 'low' | 'medium' | 'high';
  headline: string;
  failures: Failure[];
  notes: string[];
  reviewDays: number;
  storedScore: number;
}

export interface HomeTool {
  key: HomeToolKey;
  name: string;
  shortName: string;
  version: string;
  purpose: string;
  who: string;
  /** How often, in days, by default. */
  everyDays: number;
  sources: { label: string; url: string }[];
  sections: Section[];
  /** Extra checks that need the home's records or several answers together. */
  extra?(a: Answers, ctx: HomeContext): { failures: Failure[]; notes: string[] };
}

// A yes/no check where the failing answer is "No" (or "Yes" when inverted).
function chk(key: string, label: string, severity: Severity, action: string, opts: { hint?: string; failOn?: 'no' | 'yes'; na?: boolean } = {}) {
  const failOn = opts.failOn || 'no';
  const yes: CheckOption = { value: 'yes', label: 'Yes', ...(failOn === 'yes' ? { fail: severity, action } : {}) };
  const no: CheckOption = { value: 'no', label: 'No', ...(failOn === 'no' ? { fail: severity, action } : {}) };
  // The safe answer always comes first.
  const options: CheckOption[] = [...(failOn === 'yes' ? [no, yes] : [yes, no]), ...(opts.na ? [{ value: 'na', label: 'Not applicable' }] : [])];
  return { key, label, hint: opts.hint, type: 'choice' as const, options };
}

