export const HOME_TOOLS: Record<HomeToolKey, HomeTool> = {
  fire_risk_assessment: fra, fire_safety_checks: fireChecks, evacuation, window_restrictors: windows, hot_water: hotWater,
  legionella, coshh, lifting_equipment: lifting, night_working: night, oxygen_storage: oxygen, electrical_gas: electrical,
};
export const HOME_TOOL_ORDER: HomeToolKey[] = [
  'fire_risk_assessment', 'fire_safety_checks', 'evacuation', 'oxygen_storage', 'window_restrictors', 'hot_water',
  'legionella', 'coshh', 'lifting_equipment', 'night_working', 'electrical_gas',
];
export function isHomeToolKey(k: unknown): k is HomeToolKey { return typeof k === 'string' && Object.prototype.hasOwnProperty.call(HOME_TOOLS, k); }

export function cleanHomeAnswers(key: HomeToolKey, raw: unknown): Answers {
  const t = HOME_TOOLS[key];
  const src = raw && typeof raw === 'object' && !Array.isArray(raw) ? raw as Record<string, unknown> : {};
  const out: Answers = {};
  for (const q of t.sections.flatMap(s => s.questions)) {
    const v = src[q.key];
    if (v === undefined || v === null || v === '') continue;
    if (q.type === 'choice') { if (q.options!.some(o => o.value === String(v))) out[q.key] = String(v); }
    else if (q.type === 'number') { const n = Number(v); if (Number.isFinite(n)) out[q.key] = n; }
    else out[q.key] = String(v).slice(0, 2000);
  }
  return out;
}

export function evaluateHome(key: HomeToolKey, a: Answers, ctx: HomeContext = {}): HomeResult {
  const t = HOME_TOOLS[key];
  const missing = missingAnswers(t, a);
  const failures: Failure[] = [];
  for (const q of t.sections.flatMap(s => s.questions)) {
    if (!q.options) continue;
    const o = (q.options as CheckOption[]).find(x => x.value === str(a[q.key]));
    if (o?.fail) failures.push({ severity: o.fail, question: q.label, action: o.action || 'Put this right.' });
  }
  const extra = t.extra ? t.extra(a, ctx) : { failures: [], notes: [] };
  failures.push(...extra.failures);
  const rank: Record<Severity, number> = { critical: 0, major: 1, minor: 2 };
  failures.sort((x, y) => rank[x.severity] - rank[y.severity]);
  const crit = failures.filter(f => f.severity === 'critical').length;
  const major = failures.filter(f => f.severity === 'major').length;
  const level = crit ? 'high' : major ? 'medium' : 'low';
  const headline = crit ? `${crit} critical — act today` : major ? `${major} to put right this week` : failures.length ? `${failures.length} minor improvement${failures.length === 1 ? '' : 's'}` : 'All checks passed';
  return {
    complete: missing.length === 0, missing, errors: [], level, headline, failures, notes: extra.notes,
    // Something critical: check again within a week, whatever the usual interval.
    reviewDays: crit ? Math.min(7, t.everyDays) : t.everyDays,
    storedScore: failures.length,
  };
}
